      choices: ["プロセスの次の承認者に委任承認者を追加する。","プロセスで更新される項目で表示するように、項目レベルセキュリティを更新する。","次の承認者のユーザーが無効または失効していないか確認する。","ページレイアウトを見直し、プロセスで更新された項目が表示されていることを確認する。"],
