      explanation: `管理者はユーザーのレコード詳細ページからパスワードをリセットすることができます。パスワードリセット後、ユーザーは新しいパスワードでログインでき、これによりアカウントのロックも自動的に解除されます。ユーザーはすぐにシステムにアクセスを再開できます。
        管理者はユーザーのレコード詳細ページにある[ロック解除]ボタンを使用して、ロックアウトされたユーザーのアカウントを解除できます。この操作により、ユーザーは再びログインを試みることができます。
        ※ 管理者が他のユーザーとしてログインする機能は、トラブルシューティングやサポート目的で使用されますが、ロックアウトされたユーザーには適用できません。ロックアウト中のユーザーにはアクセスできないため、このオプションは適切ではありません。
        ※ パスワードポリシーのリセットという操作は存在しません。パスワードポリシーは組織全体のセキュリティ設定であり、特定のユーザーのロックアウトを解除するための手段ではありません。`
