      choices: ["ケースをキューに割り当てるフローを作成する。","割り当てルールを使用して、キューをケースの所有者に設定する。","既存のキューに利用可能なオブジェクトとしてケースを追加する。","新しいキューを作成し、利用可能なオブジェクトとしてケースを追加する。"],
