    choices: ["コースに社員の複数選択リストと平均得点を持たせる","社員にコースへの参照項目と最新得点を持たせる","社員とコースの外部IDを共通の値にそろえる","受講オブジェクトに社員とコースへの関係を持たせる"],
    answers: [3],
    explanation: "受講という関係自体に属性があるため、連結オブジェクトの各レコードとして保存します。同じ社員とコースの再受講も別レコードで保持できます。連結オブジェクトを作るだけで親2件の組み合わせが一意になるわけではありません。\n        ※ コースに社員の複数選択リストと平均得点を持たせる：複数選択リストでは個々の受講を独立したレコードとして集計・更新できません。\n        ※ 社員にコースへの参照項目と最新得点を持たせる：参照項目が一つでは複数コースと各受講時点の得点を保持できません。\n        ※ 社員とコースの外部IDを共通の値にそろえる：外部IDは連携の照合キーです。同じ値を保存しても多対多の関係レコードは作られません。",
