    explanation: "新規作成時には現在値で重要かを判定します。更新時には現在値が重要で、以前の値が重要ではなかったことを判定します。変更検知だけでは新規作成の扱いが不明確になり、現在値だけでは再通知が発生します。\n        ※ 作成か更新かを問わず、現在の優先度が重要である：重要のまま説明を変更した場合も通知条件に一致します。\n        ※ 更新であり、優先度の値が何らかの値へ変わっている：重要から通常へ変わった更新も含んでしまいます。\n        ※ 以前の優先度が重要で、現在の説明が以前と異なる：通知不要と指定された重要ケースの説明修正を選んでいます。",
