    explanation: "ローンチパッドの内部の入口は利用者のアクセス権に従います。ページを共有するだけでタブやオブジェクトの権限が付与されるわけではありません。外部サイトへのリンクはモバイルブラウザーで開かれ、Salesforceへのログインだけで外部サイトの認証が保証されるわけでもありません。\n        ※ 外部サイトへの入口は、Salesforceのレコード詳細として表示される：外部Webサイトを、Salesforceのレコード詳細画面へ変換する機能ではありません。\n        ※ 商談への入口は、ページを割り当てれば利用者全員に公開される：コンポーネントの配置は、商談タブやレコードのアクセスを拡張しません。\n        ※ 外部サイトへの入口は、Salesforceの権限セットでサイト認証も完了する：リンクの設定や権限セットだけで、外部サイト側の認証方式は構成されません。",
