    choices: ["商談の項目ラベルも売上見込へ変更し、既存レポートへの同期を待つ","商談の項目API名も変更し、保存済みレポートを再実行する","フォルダーの共有を更新し、保存済みレポートへ表示名を再配布する","新規レポートで表示名を確認し、既存レポートの列名は別途扱う"],
