    choices: ["削除した1件を復元し、共有していないフォルダーへ移動する","新しい1件のフォルダーを分け、既存の4件とは別に上限を管理する","削除した1件の保全要否を確認し、ごみ箱から完全削除する","作成者へダッシュボード管理権限を追加し、上限チェックを回避する"],
    answers: [2],
    explanation: "ごみ箱に残る削除済みの動的ダッシュボードも上限に含まれます。削除済みの1件を保全要否を確認したうえで完全削除すれば、枠を解放できます。フォルダーの移動や閲覧者の権限追加では組織の件数上限は変わりません。ここでは契約上の上限を明示しており、エディション別件数の暗記を問う問題ではありません。\n        ※ 削除した1件を復元し、共有していないフォルダーへ移動する：復元やフォルダーの場所は、動的ダッシュボードの件数を減らしません。\n        ※ 新しい1件のフォルダーを分け、既存の4件とは別に上限を管理する：件数上限は組織単位であり、フォルダーごとに5件の枠が用意されるわけではありません。\n        ※ 作成者へダッシュボード管理権限を追加し、上限チェックを回避する：管理権限を付与しても契約上の動的ダッシュボード上限は回避できません。",
