    question: "管理パッケージのプロンプトを部署用に調整したいと考えています。公開元はオーバーライドを許可しており、会社は元のテンプレートとの関係を保つ方法と、独立したテンプレートとして管理する方法を比較します。利用可能な方法を2つ選びなさい。",
    choices: ["許可されたローカルのオーバーライド用バージョンを作成する","インストールされた公開元の原本を、部署の文言へ直接編集する","Sandboxで原本を編集し、公開元のテンプレートへ変更を同期する","編集権限セットを追加し、管理パッケージを未管理へ切り替える","テンプレートを複製し、独立したテンプレートとして管理する"],
