    question: "営業は承認済みテンプレートを使ってメールを生成します。テンプレートの作成、編集、有効化は管理者だけが行います。必要なライセンスとデータアクセスは確保済みです。営業へ追加する標準権限セットとして最も適切なのはどれですか。",
    choices: ["Prompt Template Userを割り当て、管理用の権限とは分離する","フローの実行権限を割り当て、テンプレートの実行権限を代用する","テンプレートの有効化だけを行い、利用者への権限付与は省略する","Prompt Template Managerを割り当て、利用者にも編集を許可する"],
