    explanation: "Prompt Template Userはテンプレートを実行する利用者向け、Prompt Template Managerは作成や管理を行う担当者向けです。利用だけに管理権限を付ける必要はありません。また、テンプレートの利用権限は、参照するCRMデータのアクセスを無条件に拡張するものでもありません。\n        ※ フローの実行権限を割り当て、テンプレートの実行権限を代用する：フロー実行とプロンプトテンプレート実行は別の権限です。\n        ※ テンプレートの有効化だけを行い、利用者への権限付与は省略する：有効な版を用意しても、利用者に必要な実行権限が付与されたことにはなりません。\n        ※ Prompt Template Managerを割り当て、利用者にも編集を許可する：必要な利用範囲より広い管理権限を付け、役割を分ける条件に合いません。",
