    choices: ["対象レコードの共有を変更し、全利用者が同じ表現になるようにする","下書きを複数回プレビューし、利用者の実行版へ自動で反映させる","プレビューした版と、現在有効なバージョンを比較する","営業の権限を管理者相当に増やし、新しい表現の再生成を待つ"],
