    question: "担当者は回答を簡潔にするため、プロンプトの指示を「3文以内」に変更しました。同時に、保証条件の取得に失敗することがあるため、指示だけで正確な条件も補えると考えています。レビューとして適切なのはどれですか。",
    choices: ["3文以内の制約を厳しくし、保証条件の取得エラーも解消する","参照資料を外して指示だけにし、条件の不一致をなくす","保証という単語を繰り返し記載し、正しい条件をモデルに思い出させる","文量の指示と、保証条件を取得する根拠データの経路を別々に確認する"],
